.ds {
  --ds-bg:var(--p-bg,#ffffff);
  --ds-surface:var(--p-surface,#f1f3f6);
  --ds-high:var(--p-high,#fafbfc);
  --ds-text:var(--p-ink,#2c333d);
  --ds-muted:var(--p-muted,#59636f);
  --ds-border:var(--p-line,#c2cad5);
  --ds-control-border:var(--p-control-border,#7b8592);
  --ds-soft:var(--p-soft,#d3e8de);
  --ds-accent:var(--p-accent,#303b48);
  --ds-on-accent:var(--p-on-accent,#ffffff);
  --ds-focus:var(--p-highlight,#6153b5);
  --ds-error:var(--p-error,#a3313e);
  --ds-success:var(--p-success,#26614f);
  --ds-warning:var(--p-warning,#805719);
  --ds-radius:var(--p-radius,24px);
  --ds-control-radius:var(--p-control-radius,16px);
  --ds-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
  --ds-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-glass:var(--p-glass,#f6f8fbe8);
  --ds-disabled:var(--p-disabled,#dce1e8);
  --ds-duration:var(--p-duration,140ms);
  --ds-font:var(--p-font,Pretendard, sans-serif);
  --ds-display-font:var(--p-display-font,Outfit, Pretendard, sans-serif);
  --ds-text-sm:var(--p-text-sm,13px);
  --ds-text-md:var(--p-text-md,16px);
  --ds-text-lg:var(--p-text-lg,24px);
  --ds-space-2:var(--p-space-xs,8px);
  --ds-space-3:var(--p-space-sm,12px);
  --ds-space-4:var(--p-space-md,16px);
  --ds-space-6:var(--p-space-lg,24px);
  --ds-space-8:var(--p-space-xl,32px);
}
.ds {
  color:var(--ds-text); background:var(--ds-bg); font:var(--ds-text-md)/1.5 var(--ds-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-text-sm); margin-top:var(--ds-space-3); min-height:20px; color:var(--ds-muted); }
.ds .ds-surface { border:1px solid var(--ds-border); border-radius:var(--ds-radius); background:var(--ds-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-shadow); border-color:#ffffff; }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-inset); background:var(--ds-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-high); box-shadow:0 8px 24px #38465e12; }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds .ds-tablist { display:flex; padding:5px; border:1px solid var(--ds-border); border-radius:20px; gap:4px; background:var(--ds-bg); box-shadow:var(--ds-inset); }
.ds .ds-tab { flex:1; min-width:44px; min-height:44px; padding:10px 12px; border:1px solid transparent; border-radius:14px; background:transparent; font-size:14px; color:var(--ds-muted); font-weight:550; }
.ds .ds-tab:hover { background:var(--ds-surface); }
.ds .ds-tab[aria-selected="true"] { background:var(--ds-accent); color:var(--ds-on-accent); font-weight:650; box-shadow:0 2px 5px #24314526; }
.ds .ds-tabpanel { padding:var(--ds-space-6) 4px; font-size:14px; }
/* Looks: one tab markup, four structures. The chosen tab always gains a mark or a shape change, never only a color. */
.ds .ds-tabs[data-look] .ds-tab { display:inline-flex; justify-content:center; align-items:center; gap:6px; }
.ds .ds-tabs[data-look] .ds-tab .ui-icon { width:22px; height:22px; }
/* 06 icon: picture over the name, a soft capsule behind the chosen picture */
.ds .ds-tabs[data-look="icon"] .ds-tablist { padding:0; border:0; border-bottom:1px solid var(--ds-border); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="icon"] .ds-tab { flex-direction:column; gap:4px; min-height:64px; padding:8px; border-radius:0; font-size:12px; }
.ds .ds-tabs[data-look="icon"] .ds-tab .ui-icon { box-sizing:content-box; padding:4px 16px; border-radius:999px; }
.ds .ds-tabs[data-look="icon"] .ds-tab[aria-selected="true"] { background:transparent; color:var(--ds-text); box-shadow:none; }
.ds .ds-tabs[data-look="icon"] .ds-tab[aria-selected="true"] .ui-icon { background:var(--ds-soft); stroke-width:2.2; }
/* 07 vertical: list on the left, a side bar on the chosen row; arrows go up and down */
.ds .ds-tabs[data-look="vertical"] { display:grid; grid-template-columns:minmax(96px,auto) minmax(0,1fr); align-items:start; }
.ds .ds-tabs[data-look="vertical"] .ds-tablist { flex-direction:column; padding:0 8px 0 0; gap:2px; border:0; border-right:1px solid var(--ds-border); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="vertical"] .ds-tab { justify-content:flex-start; border-radius:10px 0 0 10px; }
.ds .ds-tabs[data-look="vertical"] .ds-tab[aria-selected="true"] { background:var(--ds-surface); color:var(--ds-text); box-shadow:inset 3px 0 0 var(--ds-accent); }
.ds .ds-tabs[data-look="vertical"] .ds-tabpanel { padding:12px 16px; }
/* count: how many wait behind each tab, so nobody opens tabs one by one to find out */
.ds .ds-tab-count { display:inline-grid; place-items:center; min-width:20px; height:20px; padding:0 6px; border-radius:99px; background:var(--ds-soft); color:var(--ds-text); font-size:12px; font-weight:700; line-height:1; }
.ds .ds-tabs[data-look="count"] .ds-tab { white-space:nowrap; padding-inline:8px; }
.ds .ds-tab[aria-selected="true"] .ds-tab-count { background:var(--ds-on-accent); color:var(--ds-accent); }

'use client';
import React, { useId, useState } from 'react';
const defaults = [{ value: 'all', label: '전체', content: '모든 컬렉션을 보고 있어요.' }, { value: 'progress', label: '진행 중', content: '진행 중인 컬렉션을 보고 있어요.' }, { value: 'done', label: '완료', content: '완료한 컬렉션을 보고 있어요.' }];
// look matches the HTML data-look values; the vertical look stacks the tabs and moves with the up and down arrows.
// An item's count shows how many wait behind that tab and joins its accessible name ("진행 중 2개").
export function Tabs({ items = defaults, value, defaultValue, onValueChange, label = '컬렉션 분류', look = 'filled' }) {
  const id = useId(); const [local, setLocal] = useState(defaultValue ?? items[0]?.value);
  const chosen = value ?? local;
  const active = items.some(item => item.value === chosen) ? chosen : items[0]?.value;
  const vertical = look === 'vertical';
  const [back, forward] = vertical ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'];
  function select(next) { setLocal(next); onValueChange?.(next); }
  function keydown(event, index) {
    if (![back, forward, 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : (index + (event.key === forward ? 1 : -1) + items.length) % items.length;
    event.currentTarget.parentElement.children[next].focus(); select(items[next].value);
  }
  return <div className="ds-tabs" data-look={look}><div role="tablist" className="ds-tablist" aria-label={label} aria-orientation={vertical ? 'vertical' : undefined}>{items.map((item, i) => <button type="button" key={item.value} id={`${id}-tab-${i}`} className="ds-tab" role="tab" aria-selected={active === item.value} aria-controls={`${id}-panel-${i}`} tabIndex={active === item.value ? 0 : -1} onClick={() => select(item.value)} onKeyDown={event => keydown(event, i)} aria-label={item.count != null ? `${item.label} ${item.count}개` : undefined}>{item.icon}{item.label}{item.count != null && <span className="ds-tab-count" aria-hidden="true">{item.count}</span>}</button>)}</div>{items.map((item, i) => <div key={item.value} id={`${id}-panel-${i}`} className="ds-tabpanel" role="tabpanel" aria-labelledby={`${id}-tab-${i}`} hidden={active !== item.value} tabIndex={0}>{item.content}</div>)}</div>;
}

